// Receive the actual application-model definition and its published Python
// import. The checked-in binding was regenerated by c1a67aed6; this test keeps
// that composition observable without a stand-in definition.
func TestJSONSchemaValidatesAppmodelEnvelopes(t *testing.T) {
	src := privateInput(t, "..", "..", "openabstractions-flat", "abstraction-facade", "appmodel.thrift")
	raw, err := os.ReadFile(src)
	if err != nil {
		t.Fatal(err)
	}
	mustParse(t, string(raw))
	dir := t.TempDir()
	var report bytes.Buffer
	if err := run([]string{src, dir, "jsonschema"}, &report); err != nil {
		t.Fatal(err)
	}
	schemaRaw, err := os.ReadFile(filepath.Join(dir, "jsonschema", "abstraction", "facade", "appmodel", "Envelope.schema.json"))
	if err != nil {
		t.Fatalf("%v\n%s", err, report.String())
	}
	schema := decodeJSON(t, string(schemaRaw)).(map[string]any)
	valid := `{"job":{"instance":"i1","job":"j1"}}`
	if err := schemaCheck(schema, schema, decodeJSON(t, valid)); err != nil {
		t.Fatal(err)
	}
	for _, bad := range []string{
		`{}`,
		`{"job":{"instance":"i1","job":"j1","extra":true}}`,
		`{"job":{"instance":"i1"}}`,
		`{"job":{"instance":7,"job":"j1"}}`,
		`{"job":{"instance":"i1","job":"j1"},"unknown":{}}`,
	} {
		if schemaCheck(schema, schema, decodeJSON(t, bad)) == nil {
			t.Errorf("schema accepted %s", bad)
		}
	}
	pyRoot, err := filepath.Abs(privateInput(t, "..", "..", "openabstractions-flat", "abstraction-facade", "py"))
	if err != nil {
		t.Fatal(err)
	}
	cmd := exec.Command(servicePython(t), "-B", "-c", `
import sys
sys.path.insert(0, sys.argv[1])
from abstraction.facade import appmodel
value = appmodel.from_json(appmodel.Envelope, b'{"job":{"instance":"i1","job":"j1"}}')
assert appmodel.from_json(appmodel.Envelope, appmodel.to_json(value)) == value
# Exercise the existing stack reader beyond Python's recursive-call limit.
nested = b'{"context":{"instance":"i","context":"c","epoch":"e"},"arguments":' + b'['*600 + b'0' + b']'*600 + b',"mode":"apply","expected_revision":"","idempotency_key":"k"}'
deep = appmodel.from_json(appmodel.Invocation, nested)
assert appmodel.from_json(appmodel.Invocation, appmodel.to_json(deep)) == deep
print("actual appmodel public codec received")
`, pyRoot)
	if out, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("actual appmodel public binding: %v\n%s", err, out)
	}
}

// The corpus verdict is compared against the generated reader, including its
// derivation checks. Only the backend's documented reader-only restrictions
// can account for a schema-accept/reader-refuse difference.
func TestJSONSchemaJobCorpusMatchesReader(t *testing.T) {
	def := jobDefinition(t)
	schema := decodeJSON(t, jsonSchemaRecords(def)["Record.schema.json"]).(map[string]any)
	dir := t.TempDir()
	writeNamespaceFile(t, dir, "record/_codec.py", genPy(def))
	writeNamespaceFile(t, dir, "record/__init__.py", genPyPublic(def, genPy(def)))
	corpus, err := filepath.Abs("../test/corpus")
	if err != nil {
		t.Fatal(err)
	}
	cmd := exec.Command(servicePython(t), "-B", "-c", `
import json, pathlib, sys
sys.path.insert(0, sys.argv[1])
import record
out = {}
for path in sorted(pathlib.Path(sys.argv[2]).glob("*.json")):
    try:
        record.from_json(record.Record, path.read_bytes())
        out[path.name] = "ok"
    except record.Refusal as error:
        out[path.name] = error.word
print(json.dumps(out))
`, dir, corpus)
	raw, err := cmd.CombinedOutput()
	if err != nil {
		t.Fatalf("generated public reader: %v\n%s", err, raw)
	}
	var verdicts map[string]string
	if err := json.Unmarshal(raw, &verdicts); err != nil {
		t.Fatal(err)
	}
	if len(verdicts) == 0 {
		t.Fatal("empty corpus")
	}
	exceptions := map[string]string{
		"duplicate_field": "duplicate members",
		"duplicate_key":   "duplicate members",
		"depth_exceeded":  "depth_limit",
		"number_spelling": "number spellings",
		"bad_timestamp":   "timestamp grammar",
	}
	for name, word := range verdicts {
		t.Run(name, func(t *testing.T) {
			input := readFile(t, filepath.Join(corpus, name))
			var value any
			decoder := json.NewDecoder(bytes.NewReader(input))
			decoder.UseNumber()
			parseErr := decoder.Decode(&value)
			var trailing any
			if parseErr == nil && decoder.Decode(&trailing) != io.EOF {
				parseErr = fmt.Errorf("trailing bytes")
			}
			schemaOK := utf8.Valid(input) && parseErr == nil && schemaCheck(schema, schema, value) == nil
			if schemaOK == (word == "ok") {
				return
			}
			if reason, allowed := exceptions[word]; allowed && schemaOK {
				t.Logf("documented reader-only refusal: %s (%s)", word, reason)
				return
			}
			if word == "bad_string" && schemaOK && (name == "bad_string.lone-high-surrogate.json" || name == "bad_string.lone-low-surrogate.json") {
				t.Log("reader-only unpaired-surrogate source grammar; parsed loader loses its spelling")
				return
			}
			t.Errorf("schema accept=%v, generated reader=%s", schemaOK, word)
		})
	}
}

// encoding/json replaces either lone surrogate with U+FFFD. A schema of that
// parsed instance cannot recover which raw spelling arrived. Keep the grammar
// exception exact; paired escapes and an actual U+FFFD remain valid Unicode.
func TestJSONSchemaUnpairedSurrogateLoaderBoundary(t *testing.T) {
	def := jobDefinition(t)
	schema := decodeJSON(t, jsonSchemaRecords(def)["Record.schema.json"]).(map[string]any)
	base := decodeJSON(t, string(readFile(t, "../test/corpus/accept.base.json"))).(map[string]any)
	base["id"] = "�"
	replacement, err := json.Marshal(base)
	if err != nil {
		t.Fatal(err)
	}
	high := bytes.Replace(replacement, []byte("�"), []byte(`\ud800`), 1)
	low := bytes.Replace(replacement, []byte("�"), []byte(`\udfff`), 1)
	base["id"] = "😀"
	astral, err := json.Marshal(base)
	if err != nil {
		t.Fatal(err)
	}
	paired := bytes.Replace(astral, []byte("😀"), []byte(`\ud83d\ude00`), 1)
	cases := []string{string(replacement), string(high), string(low), string(paired), string(astral)}
	for _, raw := range cases {
		if err := schemaCheck(schema, schema, decodeJSON(t, raw)); err != nil {
			t.Fatalf("parsed valid instance: %v", err)
		}
	}
	for _, raw := range [][]byte{high, low} {
		if !reflect.DeepEqual(decodeJSON(t, string(raw)), decodeJSON(t, string(replacement))) {
			t.Fatalf("loader retained a distinguishable surrogate: %s", raw)
		}
	}
	if !reflect.DeepEqual(decodeJSON(t, string(paired)), decodeJSON(t, string(astral))) ||
		reflect.DeepEqual(decodeJSON(t, string(paired)), decodeJSON(t, string(replacement))) {
		t.Fatal("valid astral scalar lost or conflated with replacement")
	}
	dir := t.TempDir()
	writeNamespaceFile(t, dir, "record/_codec.py", genPy(def))
	writeNamespaceFile(t, dir, "record/__init__.py", genPyPublic(def, genPy(def)))
	input, err := json.Marshal(cases)
	if err != nil {
		t.Fatal(err)
	}
	cmd := exec.Command(servicePython(t), "-B", "-c", `
import json, sys
sys.path.insert(0, sys.argv[1])
import record
words = []
for raw in json.load(sys.stdin):
    try:
        record.from_json(record.Record, raw.encode("utf-8"))
        words.append("ok")
    except record.Refusal as error:
        words.append(error.word)
assert words == ["ok", "bad_string", "bad_string", "ok", "ok"], words
print(words)
`, dir)
	cmd.Stdin = bytes.NewReader(input)
	if out, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("reader grammar controls: %v\n%s", err, out)
	}
}

func TestJSONSchemaEmptyVocabulary(t *testing.T) {
	def := mustParse(t, head+`
struct Doc {
 1: required list<string> content
 2: optional list<string> critical(omit="zero")
}(document="true", unknown_fields="refuse")
vocabulary Content {}(of="Doc", names="content", critical="critical")
`)
	schema := decodeJSON(t, jsonSchemaRecords(def)["Doc.schema.json"]).(map[string]any)
	if _, exists := schema["allOf"]; exists {
		t.Fatal("empty vocabulary must omit allOf")
	}
	for _, input := range []string{`{"content":[]}`, `{"content":["future"]}`, `{"content":["future"],"critical":[]}`} {
		if err := schemaCheck(schema, schema, decodeJSON(t, input)); err != nil {
			t.Fatalf("valid %s: %v", input, err)
		}
	}
	if schemaCheck(schema, schema, decodeJSON(t, `{"content":["future"],"critical":["future"]}`)) == nil {
		t.Fatal("empty vocabulary accepted unknown critical word")
	}
}

func TestJSONSchemaVocabularyPresenceChecks(t *testing.T) {
	def := mustParse(t, head+`
enum Word { 1: read }(unknown="refuse", reader="act")
struct Child { 1: optional string note(omit="zero") }(unknown_fields="refuse")
struct Doc {
 1: required list<string> content
 2: optional list<string> critical(omit="zero")
 3: optional bool active(omit="zero")
 4: optional i32 count(omit="zero")
 5: optional string text(omit="zero")
 6: optional list<Word> items(omit="zero")
 7: optional map<string,string> labels(omit="zero")
 8: optional json payload(omit="absent")
 9: required Child child
}(document="true", unknown_fields="refuse")
vocabulary Content {
 1: "base" (when="always")
 2: "active" (when="active")
 3: "count" (when="count")
 4: "text" (when="text")
 5: "items" (when="items", strip_critical="true")
 6: "labels" (when="labels")
 7: "payload" (when="payload")
 8: "member" (when="payload.member")
 9: "note" (when="child.note")
}(of="Doc", names="content", critical="critical")
`)
	schema := decodeJSON(t, jsonSchemaRecords(def)["Doc.schema.json"]).(map[string]any)
	for _, input := range []string{
		`{"content":["base","future"],"critical":["items"],"child":{}}`,
		`{"content":["base","payload"],"payload":null,"child":{}}`,
		`{"content":["base","payload"],"payload":{"member":null},"child":{}}`,
		`{"content":["base","payload","member"],"payload":{"member":[]},"child":{}}`,
		`{"content":["base"],"active":false,"count":0,"text":"","items":[],"labels":{},"child":{"note":""}}`,
		`{"content":["base","active","count","text","items","labels","payload","member","note"],"active":true,"count":1,"text":"x","items":["read"],"labels":{"x":"y"},"payload":{"member":false},"child":{"note":"x"}}`,
	} {
		value := decodeJSON(t, input)
		if err := schemaCheck(schema, schema, value); err != nil {
			t.Fatalf("valid %s: %v", input, err)
		}
		// Dropping an always-derived word and adding an absent presence word
		// are independently refused; advisory future words remain unrestricted.
		obj := value.(map[string]any)
		obj["content"] = []any{"future"}
		if schemaCheck(schema, schema, obj) == nil {
			t.Fatalf("missing base accepted: %s", input)
		}
	}
	for _, input := range []string{
		`{"content":["base","active"],"active":false,"child":{}}`,
		`{"content":["base","count"],"count":0,"child":{}}`,
		`{"content":["base","text"],"text":"","child":{}}`,
		`{"content":["base","items"],"items":[],"child":{}}`,
		`{"content":["base","labels"],"labels":{},"child":{}}`,
		`{"content":["base","payload","member"],"payload":{"member":null},"child":{}}`,
		`{"content":["base","note"],"child":{"note":""}}`,
		`{"content":["base"],"critical":["unknown"],"child":{}}`,
		`{"content":["base"],"critical":["text"],"child":{}}`,
	} {
		if schemaCheck(schema, schema, decodeJSON(t, input)) == nil {
			t.Errorf("accepted %s", input)
		}
	}
}

func decodeJSON(t *testing.T, s string) any {
	t.Helper()
	d := json.NewDecoder(strings.NewReader(s))
	d.UseNumber()
	var v any
	if err := d.Decode(&v); err != nil {
		t.Fatal(err)
	}
	return v
}

func TestJSONSchemaMemberBounds(t *testing.T) {
	src := head + `struct Choice {
 1: optional string left(omit="absent")
 2: optional string right(omit="absent")
}(unknown_fields="refuse",schema_members="1..1")
struct Root {
 1: optional Choice choice(omit="absent")
 2: optional string other(omit="absent")
}(document="true",unknown_fields="refuse",schema_members="1..1")`
	def := mustParse(t, src)
	for _, name := range []string{"Choice", "Root"} {
		var schema map[string]any
		if err := json.Unmarshal([]byte(jsonSchemaRecords(def)[name+".schema.json"]), &schema); err != nil {
			t.Fatal(err)
		}
		valid := `{"left":"one"}`
		two := `{"left":"one","right":"two"}`
		if name == "Root" {
			valid = `{"choice":` + valid + `}`
			two = `{"choice":{"left":"one"},"other":"two"}`
		}
		if err := schemaCheck(schema, schema, decodeJSON(t, valid)); err != nil {
			t.Fatalf("%s valid: %v", name, err)
		}
		for _, bad := range []string{`{}`, two} {
			if schemaCheck(schema, schema, decodeJSON(t, bad)) == nil {
				t.Errorf("%s accepted %s", name, bad)
			}
		}
		if name == "Root" {
			for _, bad := range []string{`{"choice":{}}`, `{"choice":{"left":"one","right":"two"}}`} {
				if schemaCheck(schema, schema, decodeJSON(t, bad)) == nil {
					t.Errorf("referenced Choice accepted %s", bad)
				}
			}
		}
	}
	for _, bounds := range []string{"..1", "1..", "0..2"} {
		bounded := mustParse(t, strings.ReplaceAll(src, `schema_members="1..1"`, `schema_members="`+bounds+`"`))
		var schema map[string]any
		if err := json.Unmarshal([]byte(jsonSchemaRecords(bounded)["Choice.schema.json"]), &schema); err != nil {
			t.Fatal(err)
		}
		lo, hi, _ := strings.Cut(bounds, "..")
		if (schema["minProperties"] != nil) != (lo != "") || (schema["maxProperties"] != nil) != (hi != "") {
			t.Fatalf("open bounds %s: %v", bounds, schema)
		}
	}
}

func TestJSONSchemaActualAppmodelMemberCount(t *testing.T) {
	raw, err := os.ReadFile(privateInput(t, "..", "..", "openabstractions-flat", "abstraction-facade", "appmodel.thrift"))
	if err != nil {
		t.Fatal(err)
	}
	def := mustParse(t, string(raw))
	var schema map[string]any
	if err := json.Unmarshal([]byte(jsonSchemaRecords(def)["Envelope.schema.json"]), &schema); err != nil {
		t.Fatal(err)
	}
	job := `"job":{"instance":"i1","job":"j1"}`
	reveal := `"reveal":{"context":{"instance":"i1","context":"w1","epoch":"e1"},"entities":["9"],"style":"frame"}`
	if err := schemaCheck(schema, schema, decodeJSON(t, `{`+job+`}`)); err != nil {
		t.Fatal(err)
	}
	for _, bad := range []string{`{}`, `{` + job + `,` + reveal + `}`} {
		if schemaCheck(schema, schema, decodeJSON(t, bad)) == nil {
			t.Errorf("actual Envelope accepted %s", bad)
		}
	}
	plain := mustParse(t, strings.Replace(string(raw), `schema_members="1..1",`, "", 1))
	if fmt.Sprint(definitionHashes(def)) != fmt.Sprint(definitionHashes(plain)) {
		t.Fatal("schema annotation changed wire hashes")
	}
	for _, backend := range backends {
		if backend.emitsCode && mustEmit(t, backend, def) != mustEmit(t, backend, plain) {
			t.Errorf("schema annotation changed %s codec/API", backend.lang)
		}
		if backend.emitsCode {
			t.Logf("%s codec/API unchanged sha256=%x", backend.lang, sha256.Sum256([]byte(mustEmit(t, backend, def))))
		}
	}
	// appmodel declares no service hashes. Also exercise a reached record in
	// an actual service definition, where hash equality is non-vacuous.
	annotatedService := strings.Replace(compatFixture, `}(unknown_fields = "refuse")`, `}(unknown_fields = "refuse", schema_members="1..1")`, 1)
	before, after := definitionHashes(mustParse(t, compatFixture)), definitionHashes(mustParse(t, annotatedService))
	if len(before) == 0 || fmt.Sprint(before) != fmt.Sprint(after) {
		t.Fatal("schema declaration changed service wire hash")
	}
	if problems := compatProblems(t, compatFixture, annotatedService); len(problems) != 0 {
		t.Fatalf("schema declaration changed published service compatibility: %v", problems)
	}
	t.Logf("service hashes unchanged: %v; appmodel service hashes: %v", after, definitionHashes(def))
}
